head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getDataType]<br/>Body Column 정보를 사용하여 특정 Body Column 의 dataType 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 dataType 속성값을 조회할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다.",
        "파라미터에 해당하는 Body Column 의 dataType 속성값을 반환합니다.",
        "Body Column 의 dataType 속성을 설정하지 않은 경우 바인딩된 DataList Column 의 dataType 속성값을 반환합니다.",
        "예외 발생 시에도 undefined 값을 반환합니다.",
        "Body Column 의 dataType 속성값이 ''(Empty String)인 경우 바인딩된 DataList Column 의 dataType 속성값을 반환합니다.",
        "getDataType() 메소드는 Column 단위의 dataType 속성값을 반환하며, Cell 단위의 dataType 을 반환하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 인덱스 0(col1)=number, 인덱스 2(col3)=date 로 Body Column dataType 설정. 인덱스 1(col2)은 숨김 처리(숨김 Column 도 인덱스 포함). 인덱스 3(col4)은 Body Column dataType 미설정 + 바인딩 DataList col4 dataType=text 설정\n[절차] columnInfo(인덱스) 선택 후 getDataType 실행\n[확인] 반환 dataType 이 인덱스 0=number / 1=float / 2=date / 3=text(DataList 폴백) 인지 확인"', '', 'label1');

    // dataList 생성 + 바인딩
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 검증용 초기 데이터 설정
    //  (바인딩 DataList 의 col4 Column 은 createBasicDataList 기본 dataType='text' -> Body Column dataType 미설정 시 폴백 검증용)
    dlt_bind.setJSON([
        { "col1": "12345", "col2": "67890", "col3": "20251225", "col4": "abc" }
    ]);

    let properties = { dataList: "data:dlt_bind" };
    let cList = $c.gcm.createCList(properties);

    // target 생성 (기본 4컬럼 col1~col4)
    await $c.gcm.createBasicGridView(cList);

    // Body Column dataType 설정 : 인덱스 0(col1)=number, 인덱스 1(col2)=float, 인덱스 2(col3)=date
    //  (인덱스 3(col4)은 미설정 -> 바인딩 DataList col4 의 dataType='text' 폴백 반환)
    target1.setDataType(0, "number");
    target1.setDataType(1, "float");
    target1.setDataType(2, "date");

    // 숨겨진 Column 포함 인덱스 검증용으로 두번째 컬럼(인덱스 1) 숨김
    target1.setColumnVisible(1, false);
}



scwin.btn_getDataType_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // 파라미터에 해당하는 Body Column 의 dataType 속성값 반환
    let dataType = target1.getDataType(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getDataType(" + columnInfo + ") : " + dataType);
}
